function [OutputData,OutputVariables] = Biotite_T_All(InputData,InputVariables,AddParameters,ElOxDataDef)
% -
% XMapTools External Function: biotite thermobarometry 
%  
% List of output variables:
%       - T_HFL25   Temperature Hartmeier, Forshaw & Lanari (2026)
%       - T_W20     Temperature Wu & Chen (2015)
%       - T_H05     Temperature Henry et al. (2005)
%       - P_HFL25   Pressure (GPa) Hartmeier, Forshaw & Lanari (2026)
%
% 22 Oxygen-basis 
%
% P. Lanari - Last update 04.08.2026
% Find out more at https://xmaptools.ch

OutputVariables = {'T_HFL25','T_H05','T_W15','P_HFL25','Ti','XMg'};

OutputData = zeros(size(InputData,1),length(OutputVariables));

P_GPa = AddParameters.Values(1);

% General structural formula function for 22 oxygen
WhereMin = find(sum(InputData,2) > 50);
[MatrixSF,ElementsList] = SF_OxNorm(InputData(WhereMin,:),InputVariables,22,ElOxDataDef);

Si = MatrixSF(:,1);
Ti = MatrixSF(:,2);
Al= MatrixSF(:,3);
Fe= MatrixSF(:,4)+MatrixSF(:,5);
Mn= MatrixSF(:,6);
Mg= MatrixSF(:,7);
Ca= MatrixSF(:,8);
Na= MatrixSF(:,9);
K= MatrixSF(:,10);

XMg = Mg./(Mg+Fe);

Alvi = Al-(6-Si);
X_Ti = Ti./(Fe+Mg+Alvi+Ti);
X_Fe = Fe./(Fe+Mg+Alvi+Ti);
X_Mg = Mg./(Fe+Mg+Alvi+Ti);

A = -2.3594;
B = 4.6482e-9;
C = -1.7283;

T_H05 = zeros(size(XMg));
for i = 1:length(T_H05)
    Temp = ((log(Ti(i))-A-C.*XMg(i).^3)/B).^0.333;
    if isreal(Temp)
        T_H05(i) = Temp;
    end
end

T_W15 = exp(6.313+0.224.*log(X_Ti)-0.288.*log(X_Fe)-0.449.*log(X_Mg)+0.15.*P_GPa);
Filter = find(T_W15 < 100 | T_W15 > 1000);
T_W15(Filter) = zeros(size(Filter));

Y = bt_nn_thermometer([Si/2, Ti/2, Al/2, Fe/2, Mn/2, Mg/2]);
P_HFL25 = Y(:,1);
T_HFL25 = Y(:,2);

Filter = find(T_HFL25 > 1000);
P_HFL25(Filter) = 0;
T_HFL25(Filter) = 0;

OutputData(WhereMin,:) = [T_HFL25,T_H05,T_W15,P_HFL25,Ti,XMg];

end


